/**
 * npm run gen → for each actions/<name>/spec.json, write manifest.json,
 * action.ts and README.md beside it. spec.json is the source. Do not edit
 * the three written files by hand: edit spec.json and run gen again.
 */
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { TOKEN_SECRET, hostOf as checkedHostOf } from './common.mjs'

/** The host in the committed manifest when an action has no default server. The build replaces it. */
const PLACEHOLDER_HOST = 'your-server.invalid'
/** lib/rest.ts returns these for every operation (STANDARD_OUTPUTS there). */
const STANDARD_OUTPUTS = [
  { name: 'http_status', label: 'HTTP status', type: 'integer', description: 'The HTTP status code of the response' },
  { name: 'http_ok', label: 'HTTP OK', type: 'boolean', description: 'True when the status is 2xx' },
  { name: 'response', label: 'Response', type: 'json', description: 'The full response body' },
]

const label = (name) => name.replace(/_/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2').replace(/^./, (c) => c.toUpperCase())

function hostOf(url) {
  return url ? checkedHostOf(url) : PLACEHOLDER_HOST
}

function defaultFor(field) {
  if (field.default === undefined) return {}
  if (field.type === 'number' || field.type === 'integer') return { default: Number(field.default) }
  if (field.type === 'boolean') return { default: field.default === true || field.default === 'true' }
  return { default: field.default }
}

function exampleFor(field) {
  if (field.default !== undefined) return defaultFor(field).default
  switch (field.type) {
    case 'number': case 'integer': return 1
    case 'boolean': return false
    case 'array': return []
    case 'json': return {}
    default: return `example-${field.name}`
  }
}

function manifestOf(spec) {
  return {
    manifest_version: 1,
    key: spec.key,
    name: spec.name,
    version: spec.version,
    description: spec.description,
    icon: spec.icon,
    color: spec.color,
    category: spec.category,
    summary: `${spec.name} REST calls from a workflow. Built from the LeForge usertasks-connectors repository.`,
    setup_notes: [
      `Packaged for one ${spec.name} server (npm run package -- ${spec.key} --url <server URL>).`,
      `Set the secret "${TOKEN_SECRET}" on the Access tab${spec.auth.optional ? ' (optional for this server type)' : ''}: ${spec.auth.hint || spec.auth.label}`,
      ...(spec.setup?.items ?? []),
    ].join(' '),
    homepage: 'https://github.com/LeForgeio/usertasks-connectors',
    author: 'LeForge',
    license: 'Apache-2.0',
    tags: ['leforge', spec.key],
    operations: spec.operations.map((op) => {
      const inputs = op.inputs.map((f) => ({
        name: f.name,
        label: label(f.name),
        type: f.type,
        ...(f.required ? { required: true } : {}),
        ...(f.description ? { description: f.description } : {}),
        ...defaultFor(f),
        example: exampleFor(f),
      }))
      const clash = op.outputs.find((o) => STANDARD_OUTPUTS.some((s) => s.name === o.name))
      if (clash) throw new Error(`${spec.key}.${op.id}: the output name "${clash.name}" is kept for the standard outputs`)
      const own = op.outputs
      return {
        id: op.id,
        label: op.label,
        ...(op.description ? { description: op.description } : {}),
        inputs,
        outputs: [...own.map((o) => ({ name: o.name, label: label(o.name), type: o.type })), ...STANDARD_OUTPUTS],
        // Only a read call gets a sample: the Test button must not change data.
        ...(op.method === 'GET' ? { sample: Object.fromEntries(op.inputs.filter((f) => f.required).map((f) => [f.name, exampleFor(f)])) } : {}),
      }
    }),
    capabilities: {
      http: { hosts: [hostOf(spec.default_url)] },
      credentials: [{ name: TOKEN_SECRET, label: spec.auth.label, description: spec.auth.hint || `The ${spec.name} API token` }],
    },
    limits: { timeout_ms: 30000, memory_mb: 32 },
  }
}

function readmeOf(spec) {
  const rows = spec.operations.map((op) => `| \`${op.id}\` | ${op.label} | \`${op.method} ${op.path}\` | ${op.inputs.map((i) => `\`${i.name}\`${i.required ? '' : '?'}`).join(', ') || '-'} |`)
  return `# ${spec.name}

${spec.description}.

Generated from \`spec.json\` by \`npm run gen\`. Do not edit this file by hand.

## Package and install

\`\`\`bash
npm run package -- ${spec.key} --url ${spec.url_example || spec.default_url || 'https://your-server.example.com'}
\`\`\`

Upload \`release/${spec.key}-${spec.version}.zip\` in UserTasks: **Extensibility > Workflow actions > Upload**. Then open **Manage > Access** on the action:

1. Approve the host.
2. Set the secret \`${TOKEN_SECRET}\`${spec.auth.optional ? ' (optional: leave it empty for a server that allows anonymous calls)' : ''}. ${spec.auth.hint || ''}
${spec.setup?.items?.length ? `\nRecommended setup:\n\n${spec.setup.items.map((i) => `- ${i}`).join('\n')}\n${spec.setup.note ? `\n${spec.setup.note}\n` : ''}` : ''}
## Operations

Every operation also returns \`http_status\`, \`http_ok\` and \`response\` (the full body). A status that is not 2xx fails the step (429 and 5xx can be retried).

| Id | Name | Call | Inputs (? = optional) |
|---|---|---|---|
${rows.join('\n')}
${spec.docs_url ? `\nAPI reference: ${spec.docs_url}\n` : ''}`
}

const ACTION_TS = `// Generated by npm run gen. The calls are in spec.json.
import { restAction, type Spec } from '../../lib/rest'
import spec from './spec.json'

export default restAction(spec as unknown as Spec)
`

for (const dir of readdirSync('actions')) {
  const specPath = join('actions', dir, 'spec.json')
  if (!existsSync(specPath)) continue
  const spec = JSON.parse(readFileSync(specPath, 'utf8'))
  writeFileSync(join('actions', dir, 'manifest.json'), `${JSON.stringify(manifestOf(spec), null, 2)}\n`)
  writeFileSync(join('actions', dir, 'action.ts'), ACTION_TS)
  writeFileSync(join('actions', dir, 'README.md'), readmeOf(spec))
  console.log(`actions/${dir}: ${spec.operations.length} operations`)
}
